export const THEME_GROUP_IDS: readonly string[] = THEME_GROUPS.map((g) => g.id);

const GROUP_BY_ID = new Map<string, ThemeGroupDef>();
for (const g of THEME_GROUPS) {
  GROUP_BY_ID.set(g.id, g);
}

export function themeGroupDef(id: string): ThemeGroupDef | undefined {
  return GROUP_BY_ID.get(id);
}

export function isThemeGroupId(id: unknown): id is ThemeGroupId {
  return typeof id === 'string' && GROUP_BY_ID.has(id);
}

export function themeGroupsInCategory(category: string): ThemeGroupDef[] {
  return THEME_GROUPS.filter((g) => g.category === category);
}
